tool_use_result.originalFile:
import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  // ([validated by: accepts a bare list_sessions frame](../../../specs/hal-engine-conversation-list/spec.md#L78))
  it('accepts a bare list_sessions frame with no optional fields', () => {
    const result = validateMessage({type: 'list_sessions'});

    expect(result).toEqual({valid: true, data: {type: 'list_sessions'}});
  });

  // ([validated by: rejects invalid limit as INVALID_MESSAGE](../../../specs/hal-engine-conversation-list/spec.md#L78))
  it('rejects list_sessions with invalid limit: string', () => {
    const result = validateMessage({type: 'list_sessions', limit: 'ten'});
    expect(result).toEqual({valid: false, error: expect.stringMatching(/limit/i)});
  });

  // ([validated by: rejects invalid limit as INVALID_MESSAGE](../../../specs/hal-engine-conversation-list/spec.md#L78))
  it('rejects list_sessions with invalid limit: negative, zero, or float', () => {
    const result = validateMessage({type: 'list_sessions', limit: -1});
    expect(result).toEqual({valid: false, error: expect.stringMatching(/limit/i)});
  });

  // ([validated by: rejects invalid limit as INVALID_MESSAGE](../../../specs/hal-engine-conversation-list/spec.md#L78))
  it('rejects list_sessions with invalid limit: over max', () => {
    const result = validateMessage({type: 'list_sessions', limit: 201});
    expect(result).toEqual({valid: false, error: expect.stringMatching(/limit/i)});
  });

  // ([validated by: accepts optional non-negative integer limit](../../../specs/hal-engine-conversation-list/spec.md#L78))
  it('accepts list_sessions with valid limit: integer between 1 and 200', () => {
    const validFrames = [
      {type: 'list_sessions', limit: 1},
      {type: 'list_sessions', limit: 100},
      {type: 'list_sessions', limit: 200},
    ];

    for (const frame of validFrames) {
      const result = validateMessage(frame);
      expect(result).toEqual({valid: true, data: {type: 'list_sessions', limit: frame.limit}});
    }
  });

  // ([validated by: rejects malformed before with INVALID_MESSAGE](../../../specs/hal-engine-conversation-list/spec.md#L78))
  it('rejects list_sessions with before having invalid sessionId: empty or over 128 chars', () => {
    const result = validateMessage({
      type: 'list_sessions',
      before: {sessionId: 'x'.repeat(129), updatedAt: '2024-01-01T00:00:00Z'},
    });
    expect(result).toEqual({valid: false, error: expect.stringMatching(/before|sessionId/i)});
  });
});

